using FinanceTracker;namespace FinanceTracker;public class TransactionFilter{    private readonly IRepository<int, Transaction> repo;    public TransactionFilter(IRepository<int, Transaction> repo)    {        this.repo = repo;    }    public List<Transaction> FilterByCategory(Category c)    {        List<Transaction> t = repo.GetAll().Where(x => x.Value.Category == c).Select(x=>x.Value).ToList();        if (t == null) throw new EntityDontExist("there are no transaction of this category");        return t;    }    public List<KeyValuePair<Category,Decimal>> FilterByCondition(Predicate<Transaction> condition)    {        var t = repo.GetAll()            .Where(x => condition(x.Value))            .Select(x => new KeyValuePair<Category, Decimal>(x.Value.Category, x.Value.Amount))            .ToList();                            if (t == null) throw new EntityDontExist("no Transaction match this condition");        return t;      }    }